const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);
const onBranch = SECTION.children.some((c) => c.key === active);

<Drawer variant="permanent" size={collapsed ? 64 : "sm"}>
  {/* The parent opens the level under it; it is not a page, so it
      never takes the fill. Folded, the same click opens the flyout. */}
  <NavRow
    item={SECTION}
    collapsed={collapsed}
    onBranch={onBranch}
    expanded={open}
    onSelect={(event) =>
      collapsed
        ? setAnchorEl(event.currentTarget)
        : setOpen((previous) => !previous)
    }
  />

  {!collapsed && (
    <Collapse in={open}>
      <Stack
        sx={(theme) => ({
          gap: 0.5,
          ml: "16px",
          pl: "15px",
          borderLeft: "1px solid",
          borderColor: border.layers.card2.light,
          ...theme.applyStyles("dark", {
            borderColor: border.layers.card2.dark,
          }),
        })}
      >
        {SECTION.children.map((child) => (
          <NavRow
            key={child.key}
            item={child}
            selected={active === child.key}
            onSelect={() => setActive(child.key)}
          />
        ))}
      </Stack>
    </Collapse>
  )}

  {/* Folded, the second level has nowhere to go but beside the rail. */}
  <Menu
    anchorEl={anchorEl}
    open={anchorEl !== null}
    onClose={() => setAnchorEl(null)}
    anchorOrigin={{ vertical: "top", horizontal: "right" }}
    transformOrigin={{ vertical: "top", horizontal: "left" }}
  >
    <Typography variant="body2" sx={{ px: 1, pb: 1 }}>
      {SECTION.label}
    </Typography>
    <Divider sx={{ mb: 0.5 }} />
    {SECTION.children.map(({ key, label, Icon }) => (
      <MenuItem key={key} selected={active === key} onClick={() => go(key)}>
        <Icon size={16} />
        {label}
      </MenuItem>
    ))}
  </Menu>
</Drawer>

